import sys


def is_valid(line: str) -> bool:
    matching = {")": "(", "]": "[", "}": "{"}
    stack: list[str] = []

    for bracket in line:
        if bracket in "([{":
            stack.append(bracket)
        elif not stack or stack.pop() != matching[bracket]:
            return False

    return not stack


def main() -> None:
    first_line = sys.stdin.buffer.readline()
    if not first_line:
        return

    count = int(first_line)
    output = []
    for _ in range(count):
        line = sys.stdin.buffer.readline().decode().rstrip("\r\n")
        output.append("valid" if is_valid(line) else "invalid")

    if output:
        sys.stdout.write("\n".join(output) + "\n")


if __name__ == "__main__":
    main()

