import sys


def main() -> None:
    lines = sys.stdin.buffer
    count_line = lines.readline()
    if not count_line:
        return

    count = int(count_line)
    if count == 0:
        print()
        return

    numbers = [int(lines.readline()) for _ in range(count)]
    compacted: list[str] = []
    start = previous = numbers[0]

    for number in numbers[1:]:
        if number == previous + 1:
            previous = number
            continue

        append_run(compacted, start, previous)
        start = previous = number

    append_run(compacted, start, previous)
    print(",".join(compacted))


def append_run(output: list[str], start: int, end: int) -> None:
    if end - start >= 2:
        output.append(f"{start}-{end}")
    elif end == start + 1:
        output.extend((str(start), str(end)))
    else:
        output.append(str(start))


if __name__ == "__main__":
    main()

