use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: usize = values.next().unwrap().parse().unwrap();
    let numbers: Vec<i64> = values
        .by_ref()
        .take(n)
        .map(|value| value.parse().unwrap())
        .collect();

    let mut parts = Vec::new();
    let mut start = 0;

    while start < numbers.len() {
        let mut end = start;
        while end + 1 < numbers.len()
            && numbers[end].checked_add(1) == Some(numbers[end + 1])
        {
            end += 1;
        }

        if end - start + 1 >= 3 {
            parts.push(format!("{}-{}", numbers[start], numbers[end]));
        } else {
            for &number in &numbers[start..=end] {
                parts.push(number.to_string());
            }
        }

        start = end + 1;
    }

    println!("{}", parts.join(","));
}

