    let numbers: Vec<i128> = fields
        .take(count)
        .map(|value| value.parse().unwrap())
        .collect();
    let mut parts = Vec::new();
    let mut run_start = 0;

    for index in 1..=numbers.len() {
        let continues = index < numbers.len()
            && numbers[index - 1].checked_add(1) == Some(numbers[index]);

        if !continues {
            let run_len = index - run_start;
            if run_len >= 3 {
                parts.push(format!("{}-{}", numbers[run_start], numbers[index - 1]));
            } else {
                for value in &numbers[run_start..index] {
                    parts.push(value.to_string());
                }
            }
            run_start = index;
        }
    }

    println!("{}", parts.join(","));
}

