import sys


def main() -> None:
    lines = sys.stdin.buffer
    count = int(lines.readline())
    totals: dict[str, int] = {}

    for _ in range(count):
        name_bytes, change_bytes = lines.readline().split()
        name = name_bytes.decode()
        totals[name] = totals.get(name, 0) + int(change_bytes)

    sys.stdout.write("".join(f"{name} {totals[name]}\n" for name in sorted(totals)))


if __name__ == "__main__":
    main()

