use std::collections::BTreeMap;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines();
    let n: usize = lines.next().unwrap_or("0").trim().parse().unwrap();
    let mut totals: BTreeMap<String, i128> = BTreeMap::new();

    for line in lines.take(n) {
        let (name, change) = line.split_once(' ').unwrap();
        let change: i128 = change.trim().parse().unwrap();
        *totals.entry(name.to_owned()).or_insert(0) += change;
    }

    let mut output = String::new();
    for (name, total) in totals {
        output.push_str(&name);
        output.push(' ');
        output.push_str(&total.to_string());
        output.push('\n');
    }
    print!("{output}");
}

